<?php require_once 'config/database.php'; if(empty($_SESSION['cart'])){ header("Location: index.php"); exit; } $success=false; $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']); $address=trim($_POST['address']); $email=trim($_POST['email']); $work_phone=trim($_POST['work_phone']); $cell_phone=trim($_POST['cell_phone']); $dob=$_POST['dob']; $client_category=trim($_POST['client_category']); $remarks=trim($_POST['remarks']); if(empty($name)) $errors[]="Name is required"; if(empty($address)) $errors[]="Address is required"; if(empty($cell_phone)) $errors[]="Cell number is required"; if(empty($errors)){ try{ $pdo->beginTransaction(); $stmt=$pdo->prepare("INSERT INTO clients (name,address,email,work_phone,cell_phone,dob,client_category,remarks) VALUES (?,?,?,?,?,?,?,?)"); $stmt->execute([$name,$address,$email,$work_phone,$cell_phone,$dob,$client_category,$remarks]); $client_id=$pdo->lastInsertId(); $total=0; foreach($_SESSION['cart'] as $item){ $total+=$item['price']*$item['quantity']; } $stmt=$pdo->prepare("INSERT INTO orders (client_id,total_amount) VALUES (?,?)"); $stmt->execute([$client_id,$total]); $order_id=$pdo->lastInsertId(); $stmt=$pdo->prepare("INSERT INTO order_items (order_id,product_id,quantity,price) VALUES (?,?,?,?)"); foreach($_SESSION['cart'] as $product_id=>$item){ $stmt->execute([$order_id,$product_id,$item['quantity'],$item['price']]); } $pdo->commit(); $_SESSION['cart']=[]; $success=true; }catch(Exception $e){ $pdo->rollBack(); $errors[]="Order failed: ".$e->getMessage(); } } }
?>
