<body><div class="checkout-container"><h1><i class="fas fa-clipboard-list"></i> Complete Your Order</h1>
<?php if($success): ?>
<div class="success"><i class="fas fa-check-circle"></i> Order placed successfully! Thank you.<br><a href="index.php" style="color:#d4af7a;">Continue Shopping</a></div>
<?php else: ?>
<?php if(!empty($errors)): ?><div class="error"><?php foreach($errors as $e) echo "<i class='fas fa-exclamation-circle'></i> $e<br>"; ?></div><?php endif; ?>
<div class="order-summary"><strong>Order Summary</strong><br>Total Items: <?php echo array_sum(array_column($_SESSION['cart'],'quantity')); ?><br>Total: $<?php $sum=0; foreach($_SESSION['cart'] as $i) $sum+=$i['price']*$i['quantity']; echo number_format($sum,2); ?></div>
<form method="POST"><div class="form-group"><label>Full Name *</label><input type="text" name="name" required></div><div class="form-group"><label>Address *</label><textarea name="address" rows="2" required></textarea></div><div class="form-group"><label>Email</label><input type="email" name="email"></div><div class="form-group"><label>Work Phone</label><input type="text" name="work_phone"></div><div class="form-group"><label>Cell No. *</label><input type="text" name="cell_phone" required></div><div class="form-group"><label>Date of Birth</label><input type="date" name="dob"></div><div class="form-group"><label>Category (VIP/Regular)</label><input type="text" name="client_category"></div><div class="form-group"><label>Remarks</label><textarea name="remarks" rows="2"></textarea></div><button type="submit" class="btn-submit"><i class="fas fa-check"></i> Place Order</button></form>
<?php endif; ?>
